// Merge the per-source batches (one item each, with a `.batch` array) coming from
// all Normalize nodes, then split into fixed-size chunks. Each chunk becomes one
// output item → the single downstream HTTP node fires one upsert per chunk.
//
// Why chunk: a single INSERT ... ON CONFLICT with the whole payload (especially on
// the first run, when the watermark is empty and the entire sheet history passes)
// blows past Supabase's statement_timeout (Postgres error 57014). The GIN index on
// `raw` makes large inserts even slower. Smaller statements stay well under the limit.
// Tune CHUNK_SIZE down if you still see timeouts, up for fewer round-trips.
const CHUNK_SIZE = 100;

const all = [];
for (const it of $input.all()) {
  const b = it.json && it.json.batch;
  if (Array.isArray(b)) all.push(...b);
}

// Nothing to send this tick → emit nothing so the HTTP node doesn't POST [].
if (all.length === 0) return [];

const out = [];
for (let i = 0; i < all.length; i += CHUNK_SIZE) {
  out.push({ json: { batch: all.slice(i, i + CHUNK_SIZE) } });
}
return out;

// Normalize generic-data rows AND aggregate into a single batch item,
// so the next HTTP node makes one Supabase call per ingest tick.
//
// Watermark: we remember the max `Date` we've ever processed in Workflow Static Data
// and skip anything older than (watermark - LOOKBACK_MS) on subsequent runs.
// LOOKBACK_MS buys us tolerance for rows that arrive slightly out of order or get
// edited retroactively. To force a full re-scan, deactivate the workflow, edit
// staticData.generic_last_date in the workflow JSON (or just delete the key) and
// reactivate.
const crypto = require('crypto');
const items = $input.all();
const batch = [];

const LOOKBACK_MS = 60 * 60 * 3000; // 3 hour
const staticData  = $getWorkflowStaticData('global');
const watermarkKey = 'generic_last_date';
const lastSeen = new Date(staticData[watermarkKey] || '1970-01-01T00:00:00Z');
const cutoff   = new Date(lastSeen.getTime() - LOOKBACK_MS);
let maxDate    = lastSeen;

for (const it of items) {
  const r = it.json || {};
  // skip totally empty rows
  if (!r['Entity Name'] && !r['Date'] && !r['Summary']) continue;

  // Watermark filter: skip rows whose Date is older than cutoff.
  // Rows without a parseable Date pass through (better to upsert than to lose).
  const rowDate = r['Date'] ? new Date(r['Date']) : null;
  const rowDateValid = rowDate && !isNaN(rowDate.getTime());
  if (rowDateValid && rowDate < cutoff) continue;
  if (rowDateValid && rowDate > maxDate) maxDate = rowDate;

  const raw = { ...r };
  const hash = crypto.createHash('sha256').update(JSON.stringify(raw)).digest('hex');

  batch.push({
    source: 'generic',
    source_row_date: r['Date'] || null,
    entity_name: r['Entity Name'] || null,
    entity_url: r['Company URL'] || null,
    entity_domain: null,
    headquarters: r['Headquarters'] || null,
    impacted: r['Impacted'] || null,
    leak_size: null,
    threat_actor: r['Threat Actor'] || null,
    breach_date: r['Date of Breach'] || null,
    date_published: r['Date Published'] || null,
    information_compromised: r['Information Compromised'] || null,
    description: null,
    summary: r['Summary'] || null,
    discovery_link: r['Link to Where I Found Out About the Breach'] || null,
    external_source_link: r['External Source Link'] || null,
    competitor_activity: null,
    raw: raw,            // PostgREST handles JSONB natively — pass as object
    row_hash: hash,
  });
}

// Bump watermark only if we saw something newer than the previous high-water mark.
if (maxDate > lastSeen) {
  staticData[watermarkKey] = maxDate.toISOString();
}

// If nothing to send this tick, emit nothing so the HTTP node doesn't POST [].
if (batch.length === 0) return [];
return [{ json: { batch } }];

